// Conversion functions
function convertToCurrency(value) {
  return '$' + Text(value, '#,###');
}

// Define Table Data
// Use an array instead of Dictionary to maintain order
function getParcelInfo() {
  var data = [
    [
      '<b>Parcel ID: </b>' + $feature.MapID,
      '<b>Owner Address 1: </b>' + $feature.OwnerAddress1,
    ],
    [
      '<b>Owner Name: </b>' + $feature.Owner1,
      '<b>Owner Address 2: </b>' + $feature.OwnerAddress2,
    ],
    [
      '<b>Acres: </b>' + $feature.Acres,
      '<b>Parent Parcel: </b>' + $feature.ParentId,
    ],
  ];
  return data;
}

function getLandInfo() {
  var data = [
    [
      '<b>Land Record Serial Number:</b> ' + $feature.LRSN,
      '<b>Land Description: </b>' + $feature.LandDes1,
    ],

    [
      '<b>Last Sale Date: </b> ' + Text($feature.Sale1D, 'MM/DD/YYYY'),
      '<b>Last Sale Amount: </b>' + convertToCurrency($feature.Sale1Amt),

    ],
  ];
  return data;
}

function getValuationInfo() {
  var data = [
    [
