    ],

    [
      Text($feature.Assmnt4D, 'MM/DD/YYYY'),
      convertToCurrency($feature.LandVal4),
      convertToCurrency($feature.DwlgVal4),
      convertToCurrency($feature.TotVal4),
    ],

    [
      Text($feature.Assmnt5D, 'MM/DD/YYYY'),
      convertToCurrency($feature.LandVal5),
      convertToCurrency($feature.DwlgVal5),
      convertToCurrency($feature.TotVal5),
    ],
  ];
  return data;
}

var tableSections = [
  {
    title: 'Parcel Information',
    columns: 2,
    data: getParcelInfo(),
    addBottomMargin: true,
    isImageSection: false,
  },
  {
    title: 'Land Information',
    columns: 2,
    data: getLandInfo(),
    addBottomMargin: true,
    isImageSection: false,
  },
  {
    title: 'Valuation Information',
    columns: 4,
    data: getValuationInfo(),
    addBottomMargin: true,
    isImageSection: false,
  },
];

// Set CSS style constants
var borderTableStyle = 'border:1px solid gray';
var tableStyle = 'width:100%;padding: 2px;table-layout:fixed;';
var headerStyle =
  'font-size:20px;width:100%;background-color:#DEDEDE;font-weight:bold;';
var columnStyle = 'word-wrap:break-word;';

// Form the HTML table
var reportTable;
var borderTable = "<div style='" + borderTableStyle + "'>";
reportTable += borderTable;

// Loop over the tables and create the HTML
for (var tableProps in tableSections) {
  // Get the table properties
  var props = tableSections[tableProps];
  var title = props.title;
  var columns = props.columns;
  var tableData = props.data;
  var isImageSection = props.isImageSection;

  // Create the table
  var sectionTable = "<table style='" + tableStyle + "'>";

  // Update the column width based on the number of columns
  var sectionColumnStyle =
    columnStyle + 'width:' + Round(100 / columns, 2) + '%;';
  var sectionTableHeader =
    "<tr style='" +
    headerStyle +
    "'><td colspan=" +
    columns +
    '>' +
    title +
    '</td></tr>';
  sectionTable += sectionTableHeader;

  // Loop over each row in the table data
  for (var rowIndex in tableData) {
    var row = ''; // Initialize row to an empty string
    row += '<tr>';

    if (isImageSection) {
      if (Find('https', tableData[rowIndex]) == -1) {
        row +=
          "<td style='" +
          sectionColumnStyle +
          "'>" +
          tableData[rowIndex] +
          '</td>';
      } else {
        row +=
          "<td style='" +
          sectionColumnStyle +
          "'><img src='" +
          tableData[rowIndex] +
          "'></td>";
      }
    } else {
      // Loop over each column in the row
      for (var colIndex in tableData[rowIndex]) {
        row +=
          "<td style='" +
          sectionColumnStyle +
          "'>" +
          tableData[rowIndex][colIndex] +
          '</td>';
      }
    }
    row += '</tr>';
    sectionTable += row;
  }

  if (props.addBottomMargin) {
    sectionTable += '<tr><td colspan=' + columns + '>&nbsp;</td></tr>';
  }
  sectionTable += '</table>';
  reportTable += sectionTable;
}

// add closing tags
reportTable += '</table></div>';

return {
  type: 'text',
  text: reportTable, //this property supports html tags
};

//pull roads layer
var roads = FeatureSetByName($datastore, 'Road Centerlines')

//find centroid of parcel, buffer parcel and find intersecting road
var centroid = Centroid($feature)
var bufferParcel = Buffer($feature, 60, 'feet')
var intersectRoad = First(Intersects(bufferParcel, roads))
//return intersectRoad

//Find the closest coordinate on the road to the centroid
if(!isEmpty(intersectRoad)) {

  var pointCoord = PointToCoordinate(intersectRoad, centroid)
  var pointX = pointCoord.coordinate.x
  var pointY = pointCoord.coordinate.y

//convert from meters to decimal degrees
  var originShift = 2.0 * PI * 6378137.0 / 2.0

  var lon = (pointX / originShift) * 180.0
  var lat = (pointY / originShift) * 180.0

  lat = 180.0 / PI * (2.0 * Atan(Exp(lat * PI / 180.0)) - PI / 2.0)

//create HMTL url code
  var url = 'https://www.google.com/maps/@?api=1&map_action=pano&viewpoint=' + lat + ','+ lon + '&heading=-45&pitch=0&fov=80'
  var htmlCode = `<a href='${url}'>View</a> the parcel in Street View.`

//return HTML
  return {
    type: 'text',
    text: `<p>${htmlCode}</p>`
  }
} else {
  return {
    type: 'text',
    text: `<p>No Street View available.</p>`
  }
}

var repo_url = 'https://timmons-weblogistics.s3.us-east-1.amazonaws.com/Mathews/Parcels/'
var lrsn = $feature.LRSN 

var totalPics = $feature.NumberOfImages
var counter = 1
var photoArray = []

// Build each image tag
if(totalPics > 0) {
  while (counter <= totalPics) {
      var newPhotoURL = repo_url + lrsn + "_" + counter + ".jpg"
      var htmlFormatting =`<img src='${newPhotoURL}'>`
      Push(photoArray, htmlFormatting)
      counter++
  }
}

var concatPhotos = Concatenate(photoArray, TextFormatting.NewLine)

if(totalPics>=1) {
  return {
      type: 'text',
      text: concatPhotos
  }
} if(totalPics==0) {
    return {
      type: 'text',
      text: ""
  }
}
